:root {
  /* Primary - Ramp Yellow */
  --color-primary-50:  #FFFCDC;
  --color-primary-100: #FFF7A8;
  --color-primary-200: #FFEF7A;
  --color-primary-300: #FFE94C;
  --color-primary-400: #FFE45E;
  --color-primary-500: #FFE45E;   /* Ramp Yellow */
  --color-primary-600: #E5C84A;
  --color-primary-700: #B89E2F;
  --color-primary-800: #80701F;
  --color-primary-900: #4D420F;

  /* Secondary - Cool Black (브랜드 다크) */
  --color-secondary-500: #0E0E0E;

  /* Neutral - 다크 우선 반전 램프 (0=가장 어두운 캔버스 → 1000=가장 밝은 잉크) */
  --color-neutral-0:    #0E0E0E;   /* 페이지 캔버스 — 쿨 블랙 */
  --color-neutral-50:   #161616;   /* 살짝 떠오른 면 */
  --color-neutral-100:  #1A1A1A;   /* 카드/서피스 */
  --color-neutral-200:  #2A2A2A;   /* 보더 */
  --color-neutral-300:  #3A3A3A;   /* 강한 보더 */
  --color-neutral-500:  #7A7A7A;   /* 캡션/뮤트 텍스트 */
  --color-neutral-700:  #B5B5B5;   /* 보조 텍스트 */
  --color-neutral-800:  #DCDCDC;   /* 밝은 텍스트 */
  --color-neutral-900:  #F2F2F2;   /* 본문 텍스트 */
  --color-neutral-1000: #FFFFFF;   /* 최상위 잉크 */

  /* Semantic - 다크 위 가독 (어두운 틴트 bg + 밝은 fg) */
  --color-success-bg: #16301B;
  --color-success-fg: #6FD986;
  --color-warning-bg: #3A2E0E;
  --color-warning-fg: #F5C84A;
  --color-error-bg:   #3A1715;
  --color-error-fg:   #F08576;
  --color-info-bg:    #15263A;
  --color-info-fg:    #6FA8F0;

  /* Surface (Dark default) */
  --bg-base:     #0E0E0E;          /* 페이지 기본 — 검정 캔버스 */
  --bg-subtle:   #1A1A1A;          /* 섹션/레일 구분 */
  --bg-elevated: #1F1F1F;          /* 카드 */
  --bg-overlay:  rgba(0,0,0,0.66); /* 모달/드롭다운 */

  /* Text */
  --text-primary:    #F2F2F2;      /* 본문 */
  --text-secondary:  rgba(255,255,255,0.78);
  --text-tertiary:   rgba(255,255,255,0.55);
  --text-on-primary: #0E0E0E;      /* Yellow 위 검정 */
  --text-disabled:   #5A5A5A;

  /* Border */
  --border-default: rgba(255,255,255,0.10);
  --border-subtle:  rgba(255,255,255,0.06);
  --border-strong:  rgba(255,255,255,0.20);
  --border-focus:   #FFE45E;       /* 다크에선 옐로 포커스 링 */
}

